struct cccl_increment_t
    data::NTuple{8,UInt8}
end

function Base.getproperty(x::Ptr{cccl_increment_t}, f::Symbol)
    f === :signed_offset && return Ptr{Int64}(x + 0)
    f === :unsigned_offset && return Ptr{UInt64}(x + 0)
    return getfield(x, f)
end

function Base.getproperty(x::cccl_increment_t, f::Symbol)
    r = Ref{cccl_increment_t}(x)
    ptr = Base.unsafe_convert(Ptr{cccl_increment_t}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{cccl_increment_t}, f::Symbol, v)
    return unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::cccl_increment_t, private::Bool=false)
    return (:signed_offset, :unsigned_offset, if private
                fieldnames(typeof(x))
            else
                ()
            end...)
end

